SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF NOT EXISTS(SELECT 1 FROM sys.schemas WHERE name=N'C_operations') EXEC(N'CREATE SCHEMA [C_operations] AUTHORIZATION [dbo]');

CREATE TABLE [C_operations].campaign(
 campaign_id uniqueidentifier NOT NULL,tenant_id uniqueidentifier NOT NULL,club_id uniqueidentifier NOT NULL,name nvarchar(180) NOT NULL,description nvarchar(500) NULL,starts_on date NOT NULL,ends_on date NOT NULL,status varchar(20) NOT NULL CONSTRAINT DF_campaign_status DEFAULT 'PLANNED',created_by_account_id uniqueidentifier NOT NULL,created_at_utc datetime2(3) NOT NULL,row_version rowversion NOT NULL,
 CONSTRAINT PK_campaign PRIMARY KEY(campaign_id),CONSTRAINT UQ_campaign_tenant_id UNIQUE(tenant_id,campaign_id),CONSTRAINT UQ_campaign_club_id UNIQUE(tenant_id,club_id,campaign_id),CONSTRAINT UQ_campaign_name UNIQUE(tenant_id,club_id,name),CONSTRAINT FK_campaign_club FOREIGN KEY(tenant_id,club_id) REFERENCES [C_organization].club(tenant_id,club_id),CONSTRAINT FK_campaign_actor FOREIGN KEY(created_by_account_id) REFERENCES [C_identity].account(account_id),CONSTRAINT CK_campaign_dates CHECK(ends_on>=starts_on),CONSTRAINT CK_campaign_status CHECK(status IN('PLANNED','ACTIVE','CLOSED','CANCELLED'))
);
CREATE TABLE [C_operations].campaign_participation(
 participation_id uniqueidentifier NOT NULL,tenant_id uniqueidentifier NOT NULL,club_id uniqueidentifier NOT NULL,campaign_id uniqueidentifier NOT NULL,membership_id uniqueidentifier NOT NULL,status varchar(20) NOT NULL CONSTRAINT DF_campaign_participation_status DEFAULT 'ACTIVE',joined_at_utc datetime2(3) NOT NULL,ended_at_utc datetime2(3) NULL,created_by_account_id uniqueidentifier NOT NULL,row_version rowversion NOT NULL,
 CONSTRAINT PK_campaign_participation PRIMARY KEY(participation_id),CONSTRAINT UQ_campaign_participation_tenant_id UNIQUE(tenant_id,participation_id),CONSTRAINT UQ_campaign_participation_campaign_id UNIQUE(tenant_id,campaign_id,participation_id),CONSTRAINT UQ_campaign_participation_member UNIQUE(tenant_id,campaign_id,membership_id),CONSTRAINT FK_campaign_participation_campaign FOREIGN KEY(tenant_id,club_id,campaign_id) REFERENCES [C_operations].campaign(tenant_id,club_id,campaign_id),CONSTRAINT FK_campaign_participation_membership FOREIGN KEY(tenant_id,club_id,membership_id) REFERENCES [C_membership].club_membership(tenant_id,club_id,membership_id),CONSTRAINT FK_campaign_participation_actor FOREIGN KEY(created_by_account_id) REFERENCES [C_identity].account(account_id),CONSTRAINT CK_campaign_participation_status CHECK(status IN('ACTIVE','ENDED','WITHDRAWN')),CONSTRAINT CK_campaign_participation_dates CHECK(ended_at_utc IS NULL OR ended_at_utc>=joined_at_utc)
);
CREATE TABLE [C_operations].campaign_group(
 group_id uniqueidentifier NOT NULL,tenant_id uniqueidentifier NOT NULL,club_id uniqueidentifier NOT NULL,campaign_id uniqueidentifier NOT NULL,name nvarchar(120) NOT NULL,description nvarchar(500) NULL,status varchar(20) NOT NULL CONSTRAINT DF_campaign_group_status DEFAULT 'ACTIVE',created_by_account_id uniqueidentifier NOT NULL,created_at_utc datetime2(3) NOT NULL,row_version rowversion NOT NULL,
 CONSTRAINT PK_campaign_group PRIMARY KEY(group_id),CONSTRAINT UQ_campaign_group_tenant_id UNIQUE(tenant_id,group_id),CONSTRAINT UQ_campaign_group_campaign_id UNIQUE(tenant_id,campaign_id,group_id),CONSTRAINT UQ_campaign_group_name UNIQUE(tenant_id,campaign_id,name),CONSTRAINT FK_campaign_group_campaign FOREIGN KEY(tenant_id,club_id,campaign_id) REFERENCES [C_operations].campaign(tenant_id,club_id,campaign_id),CONSTRAINT FK_campaign_group_actor FOREIGN KEY(created_by_account_id) REFERENCES [C_identity].account(account_id),CONSTRAINT CK_campaign_group_status CHECK(status IN('ACTIVE','INACTIVE','CLOSED'))
);
CREATE TABLE [C_operations].group_assignment(
 group_assignment_id uniqueidentifier NOT NULL,tenant_id uniqueidentifier NOT NULL,campaign_id uniqueidentifier NOT NULL,group_id uniqueidentifier NOT NULL,participation_id uniqueidentifier NOT NULL,assignment_source varchar(30) NOT NULL,reason nvarchar(500) NULL,starts_at_utc datetime2(3) NOT NULL,ends_at_utc datetime2(3) NULL,assigned_by_account_id uniqueidentifier NOT NULL,
 CONSTRAINT PK_group_assignment PRIMARY KEY(group_assignment_id),CONSTRAINT UQ_group_assignment_tenant_id UNIQUE(tenant_id,group_assignment_id),CONSTRAINT FK_group_assignment_group FOREIGN KEY(tenant_id,campaign_id,group_id) REFERENCES [C_operations].campaign_group(tenant_id,campaign_id,group_id),CONSTRAINT FK_group_assignment_participation FOREIGN KEY(tenant_id,campaign_id,participation_id) REFERENCES [C_operations].campaign_participation(tenant_id,campaign_id,participation_id),CONSTRAINT FK_group_assignment_actor FOREIGN KEY(assigned_by_account_id) REFERENCES [C_identity].account(account_id),CONSTRAINT CK_group_assignment_source CHECK(assignment_source IN('INITIAL','ADMIN','REQUEST_APPROVED','APPEAL_APPROVED')),CONSTRAINT CK_group_assignment_dates CHECK(ends_at_utc IS NULL OR ends_at_utc>=starts_at_utc)
);
CREATE UNIQUE INDEX UX_group_assignment_active ON [C_operations].group_assignment(tenant_id,participation_id) WHERE ends_at_utc IS NULL;
CREATE TABLE [C_operations].associate_assignment(
 associate_assignment_id uniqueidentifier NOT NULL,tenant_id uniqueidentifier NOT NULL,campaign_id uniqueidentifier NOT NULL,group_id uniqueidentifier NOT NULL,participation_id uniqueidentifier NOT NULL,status varchar(20) NOT NULL CONSTRAINT DF_associate_assignment_status DEFAULT 'ACTIVE',starts_at_utc datetime2(3) NOT NULL,ends_at_utc datetime2(3) NULL,assigned_by_account_id uniqueidentifier NOT NULL,reason nvarchar(500) NULL,
 CONSTRAINT PK_associate_assignment PRIMARY KEY(associate_assignment_id),CONSTRAINT UQ_associate_assignment_tenant_id UNIQUE(tenant_id,associate_assignment_id),CONSTRAINT FK_associate_assignment_group FOREIGN KEY(tenant_id,campaign_id,group_id) REFERENCES [C_operations].campaign_group(tenant_id,campaign_id,group_id),CONSTRAINT FK_associate_assignment_participation FOREIGN KEY(tenant_id,campaign_id,participation_id) REFERENCES [C_operations].campaign_participation(tenant_id,campaign_id,participation_id),CONSTRAINT FK_associate_assignment_actor FOREIGN KEY(assigned_by_account_id) REFERENCES [C_identity].account(account_id),CONSTRAINT CK_associate_assignment_status CHECK(status IN('ACTIVE','ENDED','REVOKED')),CONSTRAINT CK_associate_assignment_dates CHECK(ends_at_utc IS NULL OR ends_at_utc>=starts_at_utc)
);
CREATE UNIQUE INDEX UX_associate_assignment_active_group ON [C_operations].associate_assignment(tenant_id,group_id) WHERE status='ACTIVE';
CREATE TABLE [C_operations].operational_field(
 field_id uniqueidentifier NOT NULL,tenant_id uniqueidentifier NOT NULL,club_id uniqueidentifier NOT NULL,campaign_id uniqueidentifier NOT NULL,name nvarchar(180) NOT NULL,organization nvarchar(180) NULL,description nvarchar(500) NULL,status varchar(20) NOT NULL CONSTRAINT DF_operational_field_status DEFAULT 'ACTIVE',created_by_account_id uniqueidentifier NOT NULL,created_at_utc datetime2(3) NOT NULL,
 CONSTRAINT PK_operational_field PRIMARY KEY(field_id),CONSTRAINT UQ_operational_field_tenant_id UNIQUE(tenant_id,field_id),CONSTRAINT UQ_operational_field_campaign_id UNIQUE(tenant_id,campaign_id,field_id),CONSTRAINT UQ_operational_field_name UNIQUE(tenant_id,campaign_id,name),CONSTRAINT FK_operational_field_campaign FOREIGN KEY(tenant_id,club_id,campaign_id) REFERENCES [C_operations].campaign(tenant_id,club_id,campaign_id),CONSTRAINT FK_operational_field_actor FOREIGN KEY(created_by_account_id) REFERENCES [C_identity].account(account_id),CONSTRAINT CK_operational_field_status CHECK(status IN('ACTIVE','INACTIVE'))
);
CREATE TABLE [C_operations].field_assignment(
 field_assignment_id uniqueidentifier NOT NULL,tenant_id uniqueidentifier NOT NULL,campaign_id uniqueidentifier NOT NULL,group_id uniqueidentifier NOT NULL,field_id uniqueidentifier NOT NULL,starts_on date NOT NULL,ends_on date NULL,assigned_by_account_id uniqueidentifier NOT NULL,
 CONSTRAINT PK_field_assignment PRIMARY KEY(field_assignment_id),CONSTRAINT UQ_field_assignment_tenant_id UNIQUE(tenant_id,field_assignment_id),CONSTRAINT FK_field_assignment_group FOREIGN KEY(tenant_id,campaign_id,group_id) REFERENCES [C_operations].campaign_group(tenant_id,campaign_id,group_id),CONSTRAINT FK_field_assignment_field FOREIGN KEY(tenant_id,campaign_id,field_id) REFERENCES [C_operations].operational_field(tenant_id,campaign_id,field_id),CONSTRAINT FK_field_assignment_actor FOREIGN KEY(assigned_by_account_id) REFERENCES [C_identity].account(account_id),CONSTRAINT CK_field_assignment_dates CHECK(ends_on IS NULL OR ends_on>=starts_on)
);
CREATE UNIQUE INDEX UX_field_assignment_active ON [C_operations].field_assignment(tenant_id,group_id,field_id) WHERE ends_on IS NULL;
CREATE TABLE [C_operations].group_change_request(
 group_change_request_id uniqueidentifier NOT NULL,tenant_id uniqueidentifier NOT NULL,campaign_id uniqueidentifier NOT NULL,participation_id uniqueidentifier NOT NULL,current_group_id uniqueidentifier NOT NULL,requested_group_id uniqueidentifier NOT NULL,reason nvarchar(1000) NOT NULL,status varchar(20) NOT NULL CONSTRAINT DF_group_change_request_status DEFAULT 'SUBMITTED',requested_by_account_id uniqueidentifier NOT NULL,requested_at_utc datetime2(3) NOT NULL,resolved_by_account_id uniqueidentifier NULL,resolved_at_utc datetime2(3) NULL,resolution nvarchar(1000) NULL,
 CONSTRAINT PK_group_change_request PRIMARY KEY(group_change_request_id),CONSTRAINT UQ_group_change_request_tenant_id UNIQUE(tenant_id,group_change_request_id),CONSTRAINT FK_group_change_request_participation FOREIGN KEY(tenant_id,campaign_id,participation_id) REFERENCES [C_operations].campaign_participation(tenant_id,campaign_id,participation_id),CONSTRAINT FK_group_change_request_current FOREIGN KEY(tenant_id,campaign_id,current_group_id) REFERENCES [C_operations].campaign_group(tenant_id,campaign_id,group_id),CONSTRAINT FK_group_change_request_requested FOREIGN KEY(tenant_id,campaign_id,requested_group_id) REFERENCES [C_operations].campaign_group(tenant_id,campaign_id,group_id),CONSTRAINT FK_group_change_request_requester FOREIGN KEY(requested_by_account_id) REFERENCES [C_identity].account(account_id),CONSTRAINT FK_group_change_request_resolver FOREIGN KEY(resolved_by_account_id) REFERENCES [C_identity].account(account_id),CONSTRAINT CK_group_change_request_groups CHECK(current_group_id<>requested_group_id),CONSTRAINT CK_group_change_request_reason CHECK(LEN(LTRIM(RTRIM(reason)))>0),CONSTRAINT CK_group_change_request_status CHECK(status IN('SUBMITTED','APPROVED','REJECTED','CANCELLED','APPEALED')),CONSTRAINT CK_group_change_request_resolution CHECK((status='SUBMITTED' AND resolved_by_account_id IS NULL AND resolved_at_utc IS NULL AND resolution IS NULL) OR (status<>'SUBMITTED' AND ((status IN('APPROVED','REJECTED') AND resolved_by_account_id IS NOT NULL AND resolved_at_utc IS NOT NULL AND resolution IS NOT NULL) OR status IN('CANCELLED','APPEALED'))))
);
CREATE UNIQUE INDEX UX_group_change_request_pending ON [C_operations].group_change_request(tenant_id,participation_id) WHERE status='SUBMITTED';
CREATE TABLE [C_operations].group_change_appeal(
 group_change_appeal_id uniqueidentifier NOT NULL,tenant_id uniqueidentifier NOT NULL,group_change_request_id uniqueidentifier NOT NULL,reason nvarchar(1000) NOT NULL,status varchar(20) NOT NULL CONSTRAINT DF_group_change_appeal_status DEFAULT 'SUBMITTED',requested_by_account_id uniqueidentifier NOT NULL,requested_at_utc datetime2(3) NOT NULL,resolved_by_account_id uniqueidentifier NULL,resolved_at_utc datetime2(3) NULL,resolution nvarchar(1000) NULL,
 CONSTRAINT PK_group_change_appeal PRIMARY KEY(group_change_appeal_id),CONSTRAINT UQ_group_change_appeal_tenant_id UNIQUE(tenant_id,group_change_appeal_id),CONSTRAINT FK_group_change_appeal_request FOREIGN KEY(tenant_id,group_change_request_id) REFERENCES [C_operations].group_change_request(tenant_id,group_change_request_id),CONSTRAINT FK_group_change_appeal_requester FOREIGN KEY(requested_by_account_id) REFERENCES [C_identity].account(account_id),CONSTRAINT FK_group_change_appeal_resolver FOREIGN KEY(resolved_by_account_id) REFERENCES [C_identity].account(account_id),CONSTRAINT CK_group_change_appeal_reason CHECK(LEN(LTRIM(RTRIM(reason)))>0),CONSTRAINT CK_group_change_appeal_status CHECK(status IN('SUBMITTED','APPROVED','REJECTED','CANCELLED')),CONSTRAINT CK_group_change_appeal_resolution CHECK((status='SUBMITTED' AND resolved_by_account_id IS NULL AND resolved_at_utc IS NULL AND resolution IS NULL) OR (status IN('APPROVED','REJECTED') AND resolved_by_account_id IS NOT NULL AND resolved_at_utc IS NOT NULL AND resolution IS NOT NULL) OR status='CANCELLED')
);
CREATE UNIQUE INDEX UX_group_change_appeal_pending ON [C_operations].group_change_appeal(tenant_id,group_change_request_id) WHERE status='SUBMITTED';

IF NOT EXISTS(SELECT 1 FROM [C_authorization].permission WHERE code='operations.campaign.manage') INSERT INTO [C_authorization].permission(permission_id,code,name,module,status) VALUES('BB3189A2-53B2-4CC5-9B35-1F0E81192B01','operations.campaign.manage',N'Administrar campañas','OPERATIONS','ACTIVE');
IF NOT EXISTS(SELECT 1 FROM [C_authorization].permission WHERE code='operations.group.manage') INSERT INTO [C_authorization].permission(permission_id,code,name,module,status) VALUES('BB3189A2-53B2-4CC5-9B35-1F0E81192B02','operations.group.manage',N'Administrar grupos, asociados y campos','OPERATIONS','ACTIVE');
IF NOT EXISTS(SELECT 1 FROM [C_authorization].permission WHERE code='operations.participation.manage') INSERT INTO [C_authorization].permission(permission_id,code,name,module,status) VALUES('BB3189A2-53B2-4CC5-9B35-1F0E81192B03','operations.participation.manage',N'Administrar participaciones de campaña','OPERATIONS','ACTIVE');
IF NOT EXISTS(SELECT 1 FROM [C_authorization].permission WHERE code='operations.appeal.resolve') INSERT INTO [C_authorization].permission(permission_id,code,name,module,status) VALUES('BB3189A2-53B2-4CC5-9B35-1F0E81192B04','operations.appeal.resolve',N'Resolver solicitudes y apelaciones de grupo','OPERATIONS','ACTIVE');
IF NOT EXISTS(SELECT 1 FROM [C_authorization].permission WHERE code='operations.group.read') INSERT INTO [C_authorization].permission(permission_id,code,name,module,status) VALUES('BB3189A2-53B2-4CC5-9B35-1F0E81192B05','operations.group.read',N'Consultar operación de grupos','OPERATIONS','ACTIVE');
COMMIT TRANSACTION;
